fn transpose(matrix) {
    rows = matrix.length()
    cols = matrix[0].length()
    result = []
    c = 0
    while c < cols {
        row = []
        r = 0
        while r < rows {
            row.append!(matrix[r][c])
            r = r + 1
        }
        result.append!(row)
        c = c + 1
    }
    return result
}

