fn depth(item) {
    if item.type() != "list" {
        return 0
    }
    if item.length() == 0 {
        return 1
    }
    max_d = 0
    for sub in item {
        d = depth(sub)
        if d > max_d {
            max_d = d
        }
    }
    return max_d + 1
}

