fn make_emitter() {
    listeners = {}

    fn on(event, callback) {
        if listeners[event] == none {
            listeners[event] = []
        }
        listeners[event].append!(callback)
    }

    fn emit(event, data) {
        if listeners[event] != none {
            for cb in listeners[event] {
                cb(data)
            }
        }
    }

    return {"on": on, "emit": emit}
}

