fn permutations(items) {
    if items.length() <= 1 {
        return [items]
    }
    result = []
    i = 0
    while i < items.length() {
        current = items[i]
        rest = items.slice(0, i) + items.slice(i + 1, items.length())
        for perm in permutations(rest) {
            result.append!([current] + perm)
        }
        i = i + 1
    }
    return result
}

