fn center(text, width) {
    pad_total = width - text.length()
    if pad_total <= 0 {
        return text
    }
    left_pad = pad_total / 2
    right_pad = pad_total - left_pad
    return string.generate(" ", left_pad) + text + string.generate(" ", right_pad)
}

