graph Inventory {
    stock = {}

    fn add_item(name, quantity) {
        if stock[name] == none {
            stock[name] = 0
        }
        stock[name] = stock[name] + quantity
    }

    fn remove_item(name, quantity) {
        if stock[name] == none or stock[name] < quantity {
            raise "Insufficient stock for " + name
        }
        stock[name] = stock[name] - quantity
    }

    fn check(name) {
        if stock[name] == none {
            return 0
        }
        return stock[name]
    }

    fn report() {
        for item in stock.keys() {
            print(item + ": " + stock[item].to_string())
        }
    }
}

