fn tokenize(expr) {
    tokens = []
    current = ""
    for ch in expr.chars() {
        if ch == " " {
            if current.length() > 0 {
                tokens.append!(current)
                current = ""
            }
        } else {
            if ch == "+" or ch == "-" or ch == "*" or ch == "/" {
                if current.length() > 0 {
                    tokens.append!(current)
                    current = ""
                }
                tokens.append!(ch)
            } else {
                current = current + ch
            }
        }
    }
    if current.length() > 0 {
        tokens.append!(current)
    }
    return tokens
}

