fn parse_url(url) {
    result = {}
    rest = url

    # Extract protocol
    if rest.contains("://") {
        parts = rest.split("://")
        result["protocol"] = parts[0]
        rest = parts[1]
    }

    # Extract path
    if rest.contains("/") {
        slash_pos = rest.index_of("/")
        result["host"] = rest.slice(0, slash_pos)
        result["path"] = rest.slice(slash_pos, rest.length())
    } else {
        result["host"] = rest
        result["path"] = "/"
    }

    return result
}

