    config = {}
    lines = text.split("\n")
    for line in lines {
        trimmed = line.trim()
        if trimmed.length() == 0 or trimmed.starts_with("#") {
            # skip empty lines and comments
        } else {
            if trimmed.contains("=") {
                parts = trimmed.split("=")
                key = parts[0].trim()
                value = parts[1].trim()
                config[key] = value
            }
        }
    }
    return config
}

