# Matrix represented as list of rows
fn mat_mul_row(row, matrix_b_cols) {
    result = []
    for col in matrix_b_cols {
        dot = (row .* col).reduce(0, fn(a, b) { return a + b })
        result.append!(dot)
    }
    return result
}

