fn route(method, path) {
    return match [method, path] {
        ["GET", "/"] => "Home page",
        ["GET", "/about"] => "About page",
        ["POST", "/login"] => "Login handler",
        ["GET", _] => "404: Not found",
        _ => "405: Method not allowed"
    }
}

