print(route("GET", "/unknown"))   # 404: Not found
print(route("DELETE", "/"))       # 405: Method not allowed

import "os"

graph EventLog {
    events = []

    fn log(level, message) {
        events.append!({
            "time": os.system_timestamp(),
            "level": level,
            "message": message
        })
    }

    fn errors() {
        return events.filter(e => e["level"] == "ERROR")
    }

    fn recent(n) {
        if events.length() <= n {
            return events
        }
        return events.slice(events.length() - n, events.length())
    }
}

