fn rpn(expression) {
    stack = []
    tokens = expression.split(" ")
    for token in tokens {
        result = match token {
            "+" => {
                b = stack.pop()
                a = stack.pop()
                a + b
            },
            "-" => {
                b = stack.pop()
                a = stack.pop()
                a - b
            },
            "*" => {
                b = stack.pop()
                a = stack.pop()
                a * b
            },
            _ => token.to_num()
        }
        stack.append!(result)
    }
    return stack.last()
}

print(rpn("3 4 +"))        # 7
print(rpn("5 3 + 2 *"))    # 16
print(rpn("10 2 8 * + 3 -"))  # 23

fn caesar_encrypt(text, shift) {
    alphabet = string.generate("a", "z")
    result = ""
    for ch in text.chars() {
        pos = alphabet.index_of(ch.lower())
        if pos != none {
            new_pos = (pos + shift) % 26
            new_ch = alphabet[new_pos]
            if ch == ch.upper() {
                new_ch = new_ch.upper()
            }
            result = result + new_ch
        } else {
            result = result + ch
        }
    }
    return result
}

print(caesar_encrypt("Hello World", 3))   # Khoor Zruog
print(caesar_encrypt("Khoor Zruog", -3))  # Hello World

graph Queue {
    items = []

    fn enqueue(value) {
        items.append!(value)
    }

    fn dequeue() {
        if items.is_empty() {
            raise "Queue is empty"
        }
        first = items.first()
        items = items.slice(1, items.length())
        return first
    }

    fn peek() {
        return items.first()
    }

    fn size() {
        return items.length()
    }
}

