graph Leaderboard {
    scores = {}

    fn submit(player, score) {
        if scores[player] == none or score > scores[player] {
            scores[player] = score
        }
    }

    fn top(n) {
        entries = []
        for player in scores.keys() {
            entries.append!([scores[player], player])
        }
        sorted = entries.sort().reverse()
        if sorted.length() < n {
            return sorted
        }
        return sorted.slice(0, n)
    }
}

