fn validate_form(data) {
    errors = []

    if data["name"] == none or data["name"].length() == 0 {
        errors.append!("Name is required")
    }

    if data["email"] == none or !data["email"].contains("@") {
        errors.append!("Valid email is required")
    }

    if data["age"] == none or data["age"] < 0 or data["age"] > 150 {
        errors.append!("Age must be 0-150")
    }

    return errors
}

