fn md_to_text(markdown) {
    lines = markdown.split("\n")
    result = []
    for line in lines {
        trimmed = line.trim()
        if trimmed.starts_with("### ") {
            result.append!(trimmed.slice(4, trimmed.length()).upper())
        } else {
            if trimmed.starts_with("## ") {
                result.append!(trimmed.slice(3, trimmed.length()).upper())
            } else {
                if trimmed.starts_with("# ") {
                    result.append!(trimmed.slice(2, trimmed.length()).upper())
                } else {
                    result.append!(trimmed)
                }
            }
        }
    }
    return result.join("\n")
}

md = "# Title\n## Section\nSome text here.\n### Subsection\nMore text."
print(md_to_text(md))

graph BankAccount {
    owner = "unknown"
    balance = 0

    fn deposit(amount) {
        if amount <= 0 {
            raise "Deposit amount must be positive"
        }
        balance = balance + amount
        return balance
    }

    fn withdraw(amount) {
        if amount <= 0 {
            raise "Withdrawal amount must be positive"
        }
        if amount > balance {
            raise "Insufficient funds"
        }
        balance = balance - amount
        return balance
    }

    fn get_balance() {
        return balance
    }
}

